import Foundation

func hex64(_ v: UInt64) -> String {
    let hi = String(format: "%08X", UInt32(truncatingIfNeeded: v >> 32))
    let lo = String(format: "%08X", UInt32(truncatingIfNeeded: v))
    return hi + lo
}
// ADALP-group differential harness (modelled on tests/sha3).
// Expected values come from qemu-aarch64 running oracle.s (gen_cases.py).
// Case record lives in case_struct.swift (shared with the audit runner).
// Case table lives in cases.swift (generated by gen_cases.py, expected
// values merged by merge_expected.py from the qemu-aarch64 oracle run).

var passed = 0, failed = 0, threw = 0
for cs in nbCases {
    let cpu = ARM64CPU()
    cpu.platform = .vmApple
    var prog: [UInt8] = []
    for w in [cs.word, 0xD4200000 as UInt32] { for i in 0..<4 { prog.append(UInt8((w >> (8 * i)) & 0xFF)) } }
    cpu.loadProgram(prog, at: ARM64CPU.ramBase)
    cpu.fpRegisters[cs.rd * 2] = cs.vd.0; cpu.fpRegisters[cs.rd * 2 + 1] = cs.vd.1
    cpu.fpRegisters[cs.rn * 2] = cs.vn.0; cpu.fpRegisters[cs.rn * 2 + 1] = cs.vn.1
    do { try cpu.run(maxInstructions: 1) } catch { print("THROW \(cs.name)"); threw += 1; continue }
    let got = (cpu.fpRegisters[cs.rd * 2], cpu.fpRegisters[cs.rd * 2 + 1])
    if got == cs.e { passed += 1 } else {
        failed += 1
        print("FAIL \(cs.name) got=\(hex64(got.0)),\(hex64(got.1)) want=\(hex64(cs.e.0)),\(hex64(cs.e.1))")
    }
}
print("nb: \(passed) passed, \(failed) failed, \(threw) threw")
